insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('3655d58d-5ff5-4cce-b557-0eb026172cd9', '010e0234-b4f8-452a-a4f8-a8c0e598fbb8', $$tekstfragment — zonlicht als energiebron$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-zonnebrandstof-context1.png$$,
   $$“Iedere dertig minuten vangt de aarde een hoeveelheid zonlicht op waarmee we de hele wereld een jaar lang van energie kunnen voorzien. Hier ligt voor ons de uitdaging. We moeten gebruikmaken van deze mogelijkheid.” Met deze woorden opende toenmalig kroonprins Willem Alexander in 2011 een seminar in Dresden.
naar: www.groenegrondstoffen.nl$$, 'inline'),
  ('83ab8cbc-d88a-4c3b-95d1-c444f00125e6', '010e0234-b4f8-452a-a4f8-a8c0e598fbb8', $$figuur 1 — reactor voor zonnebrandstof en structuurformule IPA$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-zonnebrandstof-context2.png$$,
   $$Wetenschappers hebben iets bedacht om zonlicht te kunnen gebruiken als ‘zonnebrandstof’. Voor deze zonnebrandstof wordt zonne-energie gebruikt die is opgevangen door zonnecellen, om water te ontleden tot waterstof en zuurstof. De gevormde waterstof wordt vervolgens door de genetisch aangepaste bacteriesoort R. eutropha met koolstofdioxide omgezet tot de zonnebrandstof isopropylalcohol (IPA). Dit proces is vereenvoudigd weergegeven in figuur 1a.
figuur 1: 1a. reactor voor het maken van zonnebrandstof — een reactor met zoutoplossing en bacteriën, met elektrode A en elektrode B die zijn verbonden met een zonnecel; bij elektrode A wordt CO₂ toegevoerd en vindt 2 H₂O → 4 H⁺ + O₂ plaats, bij elektrode B vindt 2 H⁺ → H₂ plaats; de bacteriën zetten H₂ + CO₂ om tot IPA. 1b. structuurformule IPA (isopropylalcohol): H-C(H)(H)-C(H)(OH)-C(H)(H)-H (propaan-2-ol).
Het proces in figuur 1a heeft overeenkomsten met de natuurlijke fotosynthese. Beide processen hebben bijvoorbeeld zonlicht als energiebron nodig.$$, 'inline'),
  ('69eeb892-fe95-4bd0-acf5-7bb3f60f569e', '010e0234-b4f8-452a-a4f8-a8c0e598fbb8', $$figuur 2 — fragment van hydrogenase (Fe-Cys-Thr)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-zonnebrandstof-context3.png$$,
   $$Een van de stappen in het proces waarbij bacteriën IPA produceren, is de omzetting van waterstof tot waterstofionen met behulp van ‘hydrogenasen’. Een hydrogenase is een enzym met in het reactieve deel onder andere ijzeratomen. In figuur 2 is een fragment van een hydrogenase vereenvoudigd weergegeven. Het zwavelatoom in de restgroep van de cysteïne-eenheid is gebonden aan een ijzeratoom (Fe) in plaats van aan een waterstofatoom. Deze binding is op te vatten als een atoombinding.
figuur 2: Fe gebonden aan het zwavelatoom van de restgroep van de cysteïne-eenheid (Cys), die op zijn beurt is gekoppeld aan een threonine-eenheid (Thr): Fe-Cys-Thr.$$, 'inline'),
  ('13bd61cc-92ba-4962-b0e1-60a76e11be78', '010e0234-b4f8-452a-a4f8-a8c0e598fbb8', $$de omzetting van waterstof is een halfreactie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-zonnebrandstof-context4.png$$,
   $$De omzetting van waterstof tot waterstofionen door het enzym is een halfreactie.$$, 'inline'),
  ('3bc67c89-4fd5-4ed0-90bf-e17910bedf4e', '010e0234-b4f8-452a-a4f8-a8c0e598fbb8', $$figuur 3 — grafiek optische dichtheid en IPA-concentratie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-zonnebrandstof-context5.png$$,
   $$De wetenschappers hebben onderzocht of het mogelijk is om bacteriën doelgericht IPA te laten produceren. Daarvoor hebben ze een experiment uitgevoerd waarbij waterstof en koolstofdioxide worden geleid door een suspensie van bacteriën in een verdunde zoutoplossing. De bacteriën kunnen zich in dit mengsel voortplanten. De groei van het aantal bacteriën in het mengsel werd gemeten. Hiervoor werd een maat gebruikt die de ‘optische dichtheid’ wordt genoemd. Hoe hoger de optische dichtheid, hoe meer bacteriën er in het mengsel aanwezig waren. Ook de productie van IPA door de bacteriën werd in de tijd gemeten. Beide resultaten zijn weergegeven in figuur 3.
figuur 3: grafiek met op de x-as de tijd (0-120 uur) en twee y-assen: optische dichtheid (0-3,0) en concentratie IPA (0-200 mg L⁻¹). De optische dichtheid (stippellijn) stijgt van 0 bij t=0 tot ongeveer 2,4 bij t=50 uur, piekt rond 2,8 bij t≈72 uur en daalt daarna licht naar ongeveer 2,5. De concentratie IPA (getrokken lijn) blijft laag tot ongeveer t=50 uur en stijgt daarna geleidelijk tot ongeveer 200 mg L⁻¹ bij t=120 uur.$$, 'inline'),
  ('044884c9-6880-4728-9ed3-b910c06b6975', '010e0234-b4f8-452a-a4f8-a8c0e598fbb8', $$bacteriën stoppen met groeien bij optische dichtheid 2,4$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-zonnebrandstof-context6.png$$,
   $$Als hun voedingsstoffen (zoals de zoutoplossing) opraken, stoppen de bacteriën met zich te vermenigvuldigen en gaan ze IPA produceren. In het beschreven experiment gebeurt dit wanneer de optische dichtheid van 2,4 is bereikt.$$, 'inline'),
  ('3109f27b-eccb-4bf4-ad57-4443af7708bb', '010e0234-b4f8-452a-a4f8-a8c0e598fbb8', $$uitzouten — scheiding van IPA en water$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-zonnebrandstof-context7.png$$,
   $$Om IPA van het reactiemengsel te scheiden, wordt de suspensie met bacteriën gefiltreerd. Het filtraat bevat water en onder andere opgelost IPA. Hieraan wordt vervolgens zo veel keukenzout toegevoegd dat IPA en water zich als twee lagen van elkaar scheiden. Deze scheidingsmethode heet ‘uitzouten’. Door toevoeging van het zout raken alle watermoleculen betrokken bij de hydratatie van ionen uit het keukenzout. IPA-moleculen vormen dan waterstofbruggen met elkaar en niet meer met watermoleculen. Op de uitwerkbijlage zijn twee IPA-moleculen weergegeven.$$, 'inline'),
  ('64e20bc3-1ee0-437d-88d8-f8b1accf3d48', '010e0234-b4f8-452a-a4f8-a8c0e598fbb8', $$uitwerkbijlage vraag 6 — twee IPA-moleculen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-zonnebrandstof-context8-uitwerkbijlage.png$$,
   $$uitwerkbijlage bij vraag 6: twee structuurformules van IPA-moleculen zijn afgebeeld (elk H-C(H)(H)-C(H)(OH)-C(H)(H)-H, schuin getekend); de leerling moet een waterstofbrug tussen beide moleculen tekenen en de structuurformule van een derde IPA-molecuul toevoegen dat via een waterstofbrug aan een van de andere moleculen is gebonden.$$, 'uitwerkbijlage'),
  ('fafe1d1c-4a2a-4c6d-a1b0-8ee07b15253b', '010e0234-b4f8-452a-a4f8-a8c0e598fbb8', $$batchproces — figuur 1a$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-zonnebrandstof-context9.png$$,
   $$Het proces dat beschreven wordt in deze opgave en wordt samengevat in figuur 1a, heeft eigenschappen van een batchproces.$$, 'inline'),
  ('521c6875-d8e8-4bc1-83f1-aca0d01ab0fa', '010e0234-b4f8-452a-a4f8-a8c0e598fbb8', $$verbranding van IPA en reactiewarmte$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-zonnebrandstof-context10.png$$,
   $$IPA is een energiedrager en heeft een hoge energiedichtheid. De energiedichtheid van een brandstof is de hoeveelheid energie die vrijkomt bij de volledige verbranding van een bepaalde hoeveelheid van die brandstof. De energiedichtheid van vloeibare brandstoffen wordt vaak uitgedrukt in megajoule per liter (MJ L⁻¹). De volledige verbranding van IPA is hieronder met een vergelijking weergegeven.
2 C₃H₈O (l) + 9 O₂ (g) → 6 CO₂ (g) + 8 H₂O (l)
De reactiewarmte van deze reactie is −20,1·10⁵ J mol⁻¹ IPA.$$, 'inline'),
  ('6fe3db6a-7cfd-4418-9191-ebacadc59822', 'afe47981-7efb-41e2-88fe-41e38fd74195', $$alpaca — legering van koper, nikkel en zink$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-alpaca-context1.png$$,
   $$Tom koopt een gedenkmuntje bij een dierentuin. Het muntje is gemaakt van alpaca, een legering van koper, nikkel en zink. Het materiaal wordt vanwege zijn luxe, zilverkleurige uitstraling ook wel nikkelzilver genoemd.$$, 'inline'),
  ('41d1f5a7-d533-45eb-9c7c-5618c332761d', 'afe47981-7efb-41e2-88fe-41e38fd74195', $$alpaca-12 en reactie met zoutzuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-alpaca-context2.png$$,
   $$Er zijn verschillende soorten alpaca. Elke soort bevat een specifieke verhouding van de elementen koper, nikkel en zink. Het gedenkmuntje is gemaakt van ‘alpaca-12’. Alpaca-12 bevat 12,0 massaprocent nikkel. Tom heeft met een proefje het massapercentage koper en het massapercentage zink in het muntje bepaald. Hierbij heeft hij zijn muntje in voldoende 6,0 M zoutzuur gebracht. Zowel nikkel als zink reageert volledig met zoutzuur, volgens onderstaande reacties. Koper reageert niet.
Ni + 2 H⁺ → Ni²⁺ + H₂
Zn + 2 H⁺ → Zn²⁺ + H₂$$, 'inline'),
  ('0aa8ae6b-43a7-4ba5-a653-652b1ccb2ccf', 'afe47981-7efb-41e2-88fe-41e38fd74195', $$zoutzuur met hogere pH beschikbaar$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-alpaca-context3.png$$,
   $$Tom had behalve 6,0 M zoutzuur ook zoutzuur met een hogere pH tot zijn beschikking.$$, 'inline'),
  ('ec0580f5-85a3-4c0c-b624-7c5fcd0d5e06', 'afe47981-7efb-41e2-88fe-41e38fd74195', $$massa's muntje voor en na reactie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-alpaca-context4.png$$,
   $$Nadat de reactie van nikkel en zink met zoutzuur is afgelopen, heeft Tom de overgebleven vaste stof gespoeld en gedroogd. Daarna heeft hij de massa ervan bepaald. Uit de volgende gegevens heeft hij de massapercentages van koper en zink berekend:
– Alpaca-12 bevat 12,0 massaprocent nikkel.
– De massa van het muntje vóór de reactie bedroeg 12,9 g.
– De massa van de overgebleven vaste stof na de reactie bedroeg 8,3 g.$$, 'inline'),
  ('0744bf18-809e-4da4-b367-581322027833', 'a3ad0fc0-88e4-47c4-9f4b-c5164c84cb81', $$figuur 1 — triglyceridemolecuul in lijnzaadolie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-chemie-in-olieverf-context1.png$$,
   $$Olieverf is een vloeibaar mengsel van kleurpigmenten en een olie, meestal lijnzaadolie. Lijnzaadolie bestaat uit triglyceriden. Triglyceriden zijn tri-esters van glycerol en vetzuren. In figuur 1a is de structuurformule weergegeven van een triglyceridemolecuul dat in lijnzaadolie voorkomt. In figuur 1b is een triglyceridemolecuul schematisch weergegeven.
figuur 1: 1a. structuurformule van een triglyceridemolecuul, opgebouwd uit een glycerol-ruggengraat (drie C-atomen) waarvan de drie OH-groepen zijn veresterd met de vetzuurgedeeltes C₁₇H₃₃-, C₁₇H₂₉- en C₁₇H₂₉- (elk via een estergroep -O-C(=O)-). 1b. schematische weergave van hetzelfde triglyceridemolecuul als een vertakte lijnfiguur (drie ‘armen’ vanuit de glycerol-ruggengraat).
De triglyceriden in lijnzaadolie bevatten veel C=C-bindingen.$$, 'inline'),
  ('e8077e4c-26f0-4ae5-ac0d-44b4dfce7a10', 'a3ad0fc0-88e4-47c4-9f4b-c5164c84cb81', $$drie soorten reacties bij het hard worden van olieverf$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-chemie-in-olieverf-context2.png$$,
   $$In het verleden werd in gele olieverf het kleurpigment Pb₃O₄ gebruikt. Nadat de gele olieverf op het doek is aangebracht, treden verschillende soorten reacties op waardoor de olieverf langzaam hard wordt. In deze opgave worden drie soorten reacties besproken, die in willekeurige volgorde kunnen plaatsvinden:
reactie 1: vorming van crosslinks
reactie 2: hydrolyse van triglyceriden
reactie 3: reactie van Pb₃O₄ met vetzuren$$, 'inline'),
  ('1d88b05c-256f-410d-9682-301afe08622b', 'a3ad0fc0-88e4-47c4-9f4b-c5164c84cb81', $$reactie 1 — CH2-groepen reageren met zuurstof tot crosslinks$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-chemie-in-olieverf-context3.png$$,
   $$Bij reactie 1 reageren de CH₂-groepen náást de C=C-bindingen in triglyceridemoleculen met zuurstofmoleculen uit de lucht. Hierbij worden crosslinks tussen triglyceridemoleculen gevormd, zoals schematisch is weergegeven in figuur 2 op de volgende bladzijde.$$, 'inline'),
  ('ccd59cbb-5555-4cd0-9a3b-ef2467ef59ae', 'a3ad0fc0-88e4-47c4-9f4b-c5164c84cb81', $$figuur 2 — vorming van crosslinks$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-chemie-in-olieverf-context4.png$$,
   $$figuur 2: reactieschema waarin twee triglyceridemoleculen (elk weergegeven als een vertakte lijnfiguur) via twee crosslinks (verticale streepjes) aan elkaar worden gekoppeld onder toevoeging van zuurstof (‘+ zuurstof’); links het netwerk vóór reactie 1 (geen crosslinks tussen de moleculen), rechts hetzelfde netwerk ná reactie 1 (twee moleculen zijn nu via crosslinks verbonden).$$, 'inline'),
  ('23d0f72d-7200-44a2-9faf-91b8850125c5', 'a3ad0fc0-88e4-47c4-9f4b-c5164c84cb81', $$reactie 2 — hydrolyse met afsplitsing van palmitinezuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-chemie-in-olieverf-context5.png$$,
   $$Bij reactie 2 worden sommige estergroepen van de verschillende triglyceridemoleculen gehydrolyseerd. Hierbij ontstaan onder andere vetzuurmoleculen. Op de uitwerkbijlage bij vraag 17 is de vergelijking van een hydrolysereactie in olieverf onvolledig weergegeven. Bij deze hydrolyse wordt uitsluitend het vetzuur palmitinezuur afgesplitst. Het triglyceridemolecuul op de uitwerkbijlage is een ander molecuul dan in figuur 1a.$$, 'inline'),
  ('1bf3c658-a438-4a94-ae7d-5e49cd3c6f9c', 'a3ad0fc0-88e4-47c4-9f4b-c5164c84cb81', $$uitwerkbijlage vraag 17 — onvolledige hydrolysevergelijking$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-chemie-in-olieverf-context6-uitwerkbijlage.png$$,
   $$onvolledige reactievergelijking op de uitwerkbijlage: een triglyceridemolecuul (structuurformule met vetzuurgedeeltes C₁₅H₃₁-, C₁₇H₂₉- en het af te splitsen deel dat tot palmitinezuur (C₁₅H₃₁-COOH) leidt) reageert met een onbenoemde stof (+ …) tot twee producten (… + palmitinezuur); de leerling moet de ontbrekende stof links en het triglyceride-product rechts als structuurformules aanvullen.$$, 'uitwerkbijlage'),
  ('6b3a5816-1c45-40d3-b0be-2bce6172f976', 'a3ad0fc0-88e4-47c4-9f4b-c5164c84cb81', $$reactie 3 — vetzuren reageren met Pb3O4$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-chemie-in-olieverf-context7.png$$,
   $$De vetzuurmoleculen die bij reactie 2 door de hydrolyse van triglyceriden zijn afgesplitst, reageren met het pigment Pb₃O₄ volgens reactie 3, die hieronder onvolledig is weergegeven:
8 R-COOH + Pb₃O₄ → 8 R-COO⁻ + … Pb… + … Pb… + 4 H₂O (reactie 3)
De vetzuurmoleculen en de zuurrestionen zijn in bovenstaande vergelijking weergegeven met de formules R-COOH en R-COO⁻. Hierbij stelt R een willekeurig koolwaterstofgedeelte voor.$$, 'inline'),
  ('a563c0f0-3a48-4d22-8f33-79681cb4d1a4', 'a3ad0fc0-88e4-47c4-9f4b-c5164c84cb81', $$figuur 3 — netwerk van crosslinks en loodionen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-chemie-in-olieverf-context8.png$$,
   $$De eerder beschreven hydrolyse (reactie 2) en de vervolgreactie met Pb₃O₄ (reactie 3) kunnen ook optreden bij gecrosslinkte triglyceriden die zijn ontstaan door reactie 1. Het door hydrolyse afgesplitste vetzuurmolecuul is in dat geval via een crosslink verbonden met een ander triglyceride. Zo ontstaat er door reactie 3 een gecrosslinkt R-COO⁻-ion in plaats van een vrij R-COO⁻-ion. Zowel de vrije R-COO⁻-ionen als de gecrosslinkte R-COO⁻-ionen binden de loodionen. Door het binden met loodionen wordt de verflaag extra stevig. Het ontstane netwerk is in figuur 3 schematisch weergegeven.
figuur 3: netwerk van triglyceridemoleculen (vertakte lijnfiguren), onderling verbonden door crosslinks (korte verticale streepjes) en door loodionen (grijze bollen) die elk aan twee R-COO⁻-ionen (zwarte bollen) binden; bij cijfer 1 is een binding tussen een loodion en een vrij R-COO⁻-ion aangeduid, bij cijfer 2 een binding tussen een loodion en een gecrosslinkt R-COO⁻-ion.$$, 'inline'),
  ('05cbb314-d590-4e13-a8f4-f081f4d40c82', 'a3ad0fc0-88e4-47c4-9f4b-c5164c84cb81', $$witte vlekjes door verzadigde R-COO- ionen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-chemie-in-olieverf-context9.png$$,
   $$Op sommige schilderijen zijn na honderden jaren de gele kleuren vervaagd doordat witte vlekjes zijn ontstaan op het oppervlak van deze schilderijen. Deze witte vlekjes bevatten voornamelijk verbindingen van loodionen met R-COO⁻-ionen die afkomstig zijn van verzadigde vetzuren uit de gebruikte olie. De witte vlekjes zijn ontstaan doordat beide ionsoorten zich langzaam naar het oppervlak van de verflaag verplaatsten.$$, 'inline'),
  ('84612421-fdbe-48b6-bc0a-d923f14f98ad', '8bf8918e-ca5d-4103-819f-7e23bd7658a2', $$kunstgrasmat en buta-1,3-dieen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-kunstgrasmat-context1.png$$,
   $$Al sinds 1964 worden kunstgrasmatten gebruikt, bijvoorbeeld voor voetbalvelden. Een bepaald type kunstgrasmat bestaat uit een onderlaag van bijvoorbeeld rubber of polypropeen waaraan kunstgrassprieten zijn bevestigd. Een grondstof voor rubber is buta-1,3-dieen.$$, 'inline'),
  ('320ac90a-7283-4001-9eef-8f3bce2871b1', '8bf8918e-ca5d-4103-819f-7e23bd7658a2', $$figuur 1 — LLDPE uit etheen en oct-1-een$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-kunstgrasmat-context2.png$$,
   $$Het materiaal waarmee de kunstgrassprieten worden gemaakt, is in de loop der jaren verbeterd. De sprieten worden steeds sterker, veerkrachtiger en duurzamer. LLDPE is een veelgebruikte materiaalsoort voor kunstgrassprieten. LLDPE is een copolymeer dat wordt gevormd door additie van voornamelijk etheen en een kleine hoeveelheid oct-1-een (figuur 1a). De aanwezigheid van oct-1-een zorgt ervoor dat de polymeerketens van LLDPE zijketens bevatten (figuur 1b).
figuur 1: 1a. structuurformule van oct-1-een: H₂C=CH-CH₂-CH₂-CH₂-CH₂-CH₂-CH₃. 1b. schematische weergave van een LLDPE-keten als een lange draad met korte zijketens (afkomstig van oct-1-een).$$, 'inline'),
  ('530f568a-d899-43e9-9577-6c9a5ea778e9', '8bf8918e-ca5d-4103-819f-7e23bd7658a2', $$extruderen tot polymeervezels$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-kunstgrasmat-context3.png$$,
   $$Door middel van extruderen worden van het copolymeer lange polymeervezels gevormd. Deze vezels worden verwerkt in de kunstgrasmat.$$, 'inline'),
  ('4b620c21-af3d-463e-9937-20e0de34b740', '8bf8918e-ca5d-4103-819f-7e23bd7658a2', $$figuur 2 — kristallijne en amorfe delen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-kunstgrasmat-context4.png$$,
   $$Figuur 2 geeft een vereenvoudigde weergave van de structuur van het copolymeer. De polymeerketens worden in deze figuur als lange draden voorgesteld. Er zijn delen waarin de ketens evenwijdig zijn gerangschikt. Dit noemen we de kristallijne delen. In andere delen, die amorf worden genoemd, zijn de polymeerketens kriskras door elkaar aanwezig.
figuur 2: schematische doorsnede van het copolymeer als een cirkel met kristallijne delen (evenwijdige lijnen) en amorfe delen (kriskras gebogen lijnen).
Een hoger aandeel kristallijne delen verhoogt vooral de sterkte van het kunstgras, terwijl een hoger aandeel amorfe delen het kunstgras juist veerkrachtiger maakt.$$, 'inline'),
  ('a808cfe9-500a-4f9f-80db-9c74be0844e0', '8bf8918e-ca5d-4103-819f-7e23bd7658a2', $$recycling kunstgras en cradle-to-cradle$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-kunstgrasmat-context5.png$$,
   $$Na ongeveer 10 jaar is een voetbalveld van kunstgras versleten. Het versleten kunstgras kan op verschillende manieren worden verwerkt. Kunstgrasmatten kunnen bijvoorbeeld worden verbrand in energiecentrales. Een versleten kunstgrasmat met een onderlaag van polypropeen en sprieten van LLDPE kan ook gerecycled worden. De mat wordt dan als geheel gesmolten en verwerkt tot één soort kunststofgranulaat. Dit granulaat kan worden gebruikt om bijvoorbeeld verkeerspaaltjes van te maken.
Bas meent dat bovenstaand recycle-proces past bij het cradle-to-cradle-principe. Alina is het hier niet mee eens.$$, 'inline'),
  ('fce98c0f-4d23-4536-963a-e1886944943a', '5c5565e4-e648-46b6-b3f7-8c118e16466b', $$stookolie en zwaveldioxide-uitstoot$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-scheepvaart-over-op-lng-context1.png$$,
   $$Schepen varen grotendeels op stookolie. Stookolie is een van de destillatiefracties van aardolie. Deze fractie bevat behalve koolwaterstoffen ook zwavelverbindingen. Daardoor komt bij de verbranding in de scheepsmotoren zwaveldioxide (SO₂) vrij. De uitstoot van zwaveldioxide, maar ook van koolstofdioxide, stikstofoxiden en fijnstof leidt in havens en steden tot milieuproblemen.$$, 'inline'),
  ('40144c14-8a53-4003-a525-23859a4a5e99', '5c5565e4-e648-46b6-b3f7-8c118e16466b', $$verbruik cruiseschip en Europese zwavelnorm$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-scheepvaart-over-op-lng-context2.png$$,
   $$Een groot cruiseschip verbruikt zo’n 2,4·10⁵ kg stookolie per dag. Volgens nieuwe milieueisen moet het gehalte zwavel in stookolie wereldwijd omlaag. In Europa geldt de norm van 0,1 massaprocent S.$$, 'inline'),
  ('a9ca60d5-2227-4f1a-bba5-e24c6cc2ea18', '5c5565e4-e648-46b6-b3f7-8c118e16466b', $$figuur 1 — productieproces van LNG$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-scheepvaart-over-op-lng-context3.png$$,
   $$LNG (liquified natural gas, ofwel vloeibaar aardgas) is een zwavelvrij alternatief voor stookolie. LNG wordt gemaakt uit aardgas. Aardgas bestaat voornamelijk uit methaan, met kleine hoeveelheden koolstofdioxide, waterstofsulfide (H₂S) en waterdamp. In figuur 1 is het productieproces van LNG vereenvoudigd en onvolledig weergegeven.
figuur 1: blokschema van het LNG-productieproces: aardgas (CH₄ met CO₂, H₂S en H₂O) gaat naar ruimte I; vanuit ruimte I gaat gereinigd aardgas naar ruimte III en een andere stroom naar ruimte II; vanuit ruimte II gaat een stroom weg en een stroom omlaag; vanuit ruimte III gaat een stroom omlaag en gereinigd/gedroogd aardgas naar ruimte IV; vanuit ruimte IV gaat LNG naar opslag. Diverse stofstromen zijn nog niet benoemd (aangeduid met ‘...’).$$, 'inline'),
  ('29597476-02c7-4f70-8ef4-1620ab043555', '5c5565e4-e648-46b6-b3f7-8c118e16466b', $$toelichting ruimtes I t/m IV$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-scheepvaart-over-op-lng-context4.png$$,
   $$In ruimte I worden CO₂ en H₂S door middel van een waterige oplossing (oplossing A) uit het aardgas verwijderd. In ruimte II wordt het ontstane mengsel gescheiden. Hierbij worden de gassen CO₂ en H₂S afgescheiden van oplossing A en in een ander proces verder verwerkt. Oplossing A wordt volledig gerecirculeerd. Neem hierbij aan dat er geen verlies optreedt van water uit oplossing A.
Het gereinigde aardgas wordt ‘gedroogd’ in ruimte III. De waterdamp die nog in het aardgas aanwezig is, wordt hier verwijderd. Het gedroogde aardgas gaat naar ruimte IV. Hier wordt het afgekoeld tot het aardgas vloeibaar is geworden. Dit vloeibare aardgas heet LNG. Vervolgens wordt LNG in grote tanks opgeslagen. Het onvolledige blokschema is op de uitwerkbijlage nogmaals weergegeven.$$, 'inline'),
  ('2f90c78f-0ea6-46b4-8799-2cac1fafccac', '5c5565e4-e648-46b6-b3f7-8c118e16466b', $$uitwerkbijlage vraag 30 — blokschema LNG-productie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-scheepvaart-over-op-lng-context5-uitwerkbijlage.png$$,
   $$onvolledig blokschema op de uitwerkbijlage (identiek aan figuur 1): aardgas (CH₄ met CO₂, H₂S en H₂O) → ruimte I → gereinigd aardgas → ruimte III → … → ruimte IV → LNG → opslag; vanuit ruimte I ook een stroom naar ruimte II, vanuit ruimte II een uitgaande stroom en een stroom omlaag, vanuit ruimte III een stroom omlaag; de leerling moet op de stippellijntjes de nummers van de stoffen 1 (CO₂), 2 (gedroogd aardgas), 3 (H₂O), 4 (H₂S) en 5 (oplossing A) invullen, waarbij het hergebruik (recirculatie) van oplossing A moet worden verwerkt.$$, 'uitwerkbijlage'),
  ('b94eb586-3881-4b24-a92c-da2b94df73b2', '5c5565e4-e648-46b6-b3f7-8c118e16466b', $$MDEA in oplossing A$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-scheepvaart-over-op-lng-context6.png$$,
   $$Methyldiëthanolamine (afgekort MDEA)
HO-CH₂-CH₂-N(CH₃)-CH₂-CH₂-OH
is een stof die vaak wordt gebruikt in oplossing A.$$, 'inline'),
  ('10ae92f0-1556-4ab4-9612-dc254d01e60d', '5c5565e4-e648-46b6-b3f7-8c118e16466b', $$figuur 2 — moleculaire zeef$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-scheepvaart-over-op-lng-context7.png$$,
   $$In ruimte III wordt gereinigd aardgas ‘gedroogd’. Dit drogen gebeurt met behulp van een zogeheten ‘moleculaire zeef’ (figuur 2). Een moleculaire zeef is geen zeef zoals we die uit de keuken kennen. Het zijn korrels van een stof met veel kleine poriën. Watermoleculen kunnen in de poriën, maar methaanmoleculen zijn daarvoor te groot. In de poriën worden de watermoleculen gebonden. Een moleculaire zeef maakt gebruik van twee scheidingsmethoden.
figuur 2: foto van korrels van de moleculaire zeef (kleine, ronde witte/grijze korrels).$$, 'inline'),
  ('0f4a817f-1c3f-4874-8d4f-aa0767484b25', '5c5565e4-e648-46b6-b3f7-8c118e16466b', $$temperatuurgrenzen ruimte IV bij achterblijvend water$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-scheepvaart-over-op-lng-context8.png$$,
   $$Als het water niet zou worden verwijderd in ruimte III, zou het water in ruimte IV tot problemen leiden. Dit kan worden afgeleid uit de temperatuurgrenzen waarbinnen in ruimte IV vloeibaar aardgas (vloeibaar methaan) wordt verkregen.$$, 'inline'),
  ('8a91614a-a08c-4d39-a9ad-12b8d7d9ac19', '5c5565e4-e648-46b6-b3f7-8c118e16466b', $$uitwerkbijlage vraag 33 — invullijnen temperatuurgrenzen en problemen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-scheepvaart-over-op-lng-context9-uitwerkbijlage.png$$,
   $$invullijnen op de uitwerkbijlage bij vraag 33: ‘temperatuurgrenzen waarbinnen in ruimte IV vloeibaar aardgas wordt verkregen: …’, ‘waarom water in ruimte IV tot problemen leidt: …’, ‘voorbeeld van een probleem: …’.$$, 'uitwerkbijlage'),
  ('228eea6f-4452-40dd-83ce-9697d836e63c', '5c5565e4-e648-46b6-b3f7-8c118e16466b', $$C/H-verhouding en duurzaamheid van brandstoffen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2023-i-scheepvaart-over-op-lng-context10.png$$,
   $$In discussies over duurzaamheid van brandstoffen wordt de volgende stelregel gehanteerd: “Hoe lager de C/H-verhouding in een brandstof is, hoe meer energie er zal vrijkomen bij de verbranding van 1 gram stof en hoe minder CO₂ er wordt gevormd per kJ geproduceerde energie.”
De C/H-verhouding berekent men als volgt:
C/H-verhouding = aantal C-atomen / aantal H-atomen$$, 'inline');

