  ('7940ae54-c9c6-4d0f-a88f-7df3eec9a833', 'afe47981-7efb-41e2-88fe-41e38fd74195', 12,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
